import unittest
from cart import total_cents, customer_label, clean_name

class CartTests(unittest.TestCase):
    def test_nonempty(self):
        self.assertEqual(total_cents([(125, 2), (50, 1)]), 300)

    def test_label(self):
        self.assertEqual(customer_label('Ada'), 'Customer: Ada')

    def test_label_trims_and_collapses_spaces(self):
        self.assertEqual(customer_label('  Ada   Lovelace  '),
                         'Customer: Ada Lovelace')

    def test_label_preserves_case(self):
        self.assertEqual(customer_label('  aDa   LoVeLaCe  '),
                         'Customer: aDa LoVeLaCe')

    def test_label_empty_and_whitespace_only(self):
        for name in ('', '   ', '\t\n '):
            with self.subTest(name=name):
                self.assertEqual(customer_label(name), 'Customer: ')

    def test_label_mixed_whitespace(self):
        self.assertEqual(customer_label('\tAda \n Lovelace\t'),
                         'Customer: Ada Lovelace')


class CleanNameTests(unittest.TestCase):
    def test_trims_and_collapses_spaces(self):
        self.assertEqual(clean_name('  Ada   Lovelace  '), 'Ada Lovelace')

    def test_preserves_case(self):
        self.assertEqual(clean_name('  aDa   LoVeLaCe  '), 'aDa LoVeLaCe')

    def test_empty_and_whitespace_only(self):
        for name in ('', '   ', '\t\n '):
            with self.subTest(name=name):
                self.assertEqual(clean_name(name), '')

    def test_single_name(self):
        self.assertEqual(clean_name('Ada'), 'Ada')

    def test_mixed_whitespace(self):
        self.assertEqual(clean_name('\tAda \n Lovelace\t'), 'Ada Lovelace')

